<template><main class="rule-builder"><header class="builder-header"><div><span class="eyebrow">自动化配置</span><h1>{{title}}</h1><p>将业务条件组合为可执行规则</p></div><div class="header-actions"><button class="secondary" type="button" on-click="togglePreview">{{previewOpen ? '关闭预览' : '预览表达式'}}</button><button type="button" on-click="save" disabled="{{readonly || invalidRuleCount > 0}}">保存规则</button></div></header><section class="builder-stats"><article><span>条件组</span><strong>{{groups.length}}</strong></article><article><span>规则数</span><strong>{{ruleCount}}</strong></article><article class="{{invalidRuleCount ? 'warning' : ''}}"><span>待修正</span><strong>{{invalidRuleCount}}</strong></article></section><section class="builder-workspace"><aside class="group-sidebar"><div class="sidebar-title"><strong>条件组</strong><button type="button" on-click="addGroup" disabled="{{readonly}}">+</button></div><button class="group-tab" type="button" s-for="group in groups trackby group.id" on-click="selectGroup(group.id)"><span>{{group.name}}</span><small>{{group.rules.length}} 条</small></button></aside><div class="group-editor" s-if="selectedGroup"><div class="group-toolbar"><input type="text" on-input="renameGroup($event.target.value)" value="{{selectedGroup.name}}" disabled="{{readonly}}"/><select on-change="changeMode($event.target.value)" value="{{selectedGroup.mode}}" disabled="{{readonly}}"><option value="all">满足全部</option><option value="any">满足任一</option></select><button type="button" on-click="removeGroup(selectedGroup.id)" disabled="{{readonly || groups.length === 1}}">删除组</button></div><div class="rule-list"><article s-for="(rule, index) in selectedGroup.rules trackby rule.id" class="rule-row {{!rule.value ? 'invalid' : ''}}"><span class="rule-index">{{index + 1}}</span><select on-change="updateRule(rule.id, 'field', $event.target.value)" value="{{rule.field}}" disabled="{{readonly}}"><option s-for="field in availableFields trackby field.key" value="{{field.key}}">{{field.label}}</option></select><select on-change="updateRule(rule.id, 'operator', $event.target.value)" value="{{rule.operator}}" disabled="{{readonly}}"><option value="equals">等于</option><option value="contains">包含</option><option value="greater">大于</option></select><input type="text" placeholder="比较值" on-input="updateRule(rule.id, 'value', $event.target.value)" value="{{rule.value}}" disabled="{{readonly}}"/><button type="button" on-click="removeRule(rule.id)" disabled="{{readonly}}">移除</button></article></div><button class="add-rule" type="button" on-click="addRule" disabled="{{readonly}}">添加条件</button></div><div class="empty-editor" s-else>请选择条件组</div></section><section class="expression-preview" s-if="previewOpen"><div><strong>逻辑表达式</strong><button type="button" on-click="validate">重新校验</button></div><code>{{expression}}</code><ul s-if="errors.length"><li s-for="error in errors trackby error">{{error}}</li></ul><p s-else>表达式校验通过</p></section><footer class="builder-footer"><span>最近保存：<span>{{savedAt || '尚未保存'}}</span></span><span>{{readonly ? '只读模式' : '自动保存已开启'}}</span></footer></main></template><script>const san=require("san");const DataTypes=san.DataTypes;module.exports=san.defineComponent({name:"RuleBuilder",dataTypes:{title:DataTypes.string,availableFields:DataTypes.array,initialGroups:DataTypes.array,readonly:DataTypes.bool},initData(){return {groups:null,selectedGroupId:null,previewOpen:false,errors:[],nextGroupId:3,nextRuleId:3,savedAt:"",autosaveTimer:null,draftName:"",testPayload:{}}},inited(){const initialGroups=this.data.get("initialGroups");if(typeof initialGroups==="function"){this.data.set("groups",initialGroups());}else{this.data.set("groups",initialGroups||[]);}const groups=this.data.get("groups");this.data.set("selectedGroupId",groups.length?groups[0].id:0);this.watch("groups",()=>{const groups=this.data.get("groups");this.data.set("selectedGroupId",groups.length?groups[0].id:0);});},attached(){this.validate();this.scheduleAutosave();},disposed(){clearTimeout(this.data.get("autosaveTimer"));},selectGroup(id){this.data.set("selectedGroupId",id);},addGroup(){const nextGroupId=this.data.get("nextGroupId");const groups=this.data.get("groups");const group={id:nextGroupId,name:`条件组 ${groups.length+1}`,mode:"all",rules:[]};groups.push(group);this.data.set("groups",groups);this.data.set("selectedGroupId",group.id);this.data.set("nextGroupId",nextGroupId+1);this.changed();},removeGroup(id){const groups=this.data.get("groups").filter((group)=>group.id!==id);this.data.set("groups",groups);this.data.set("selectedGroupId",groups.length?groups[0].id:0);this.changed();},renameGroup(value){const selectedGroup=this.data.get("selectedGroup");if(selectedGroup){selectedGroup.name=value;this.changed();}},changeMode(value){const selectedGroup=this.data.get("selectedGroup");if(selectedGroup){selectedGroup.mode=value;this.changed();}},addRule(){const selectedGroup=this.data.get("selectedGroup");if(selectedGroup){const nextRuleId=this.data.get("nextRuleId");const availableFields=this.data.get("availableFields");selectedGroup.rules.push({id:nextRuleId,field:availableFields[0].key,operator:"equals",value:""});this.data.set("nextRuleId",nextRuleId+1);this.changed();}},removeRule(id){const selectedGroup=this.data.get("selectedGroup");if(selectedGroup){selectedGroup.rules=selectedGroup.rules.filter((rule)=>rule.id!==id);this.changed();}},updateRule(id,key,value){const selectedGroup=this.data.get("selectedGroup");if(selectedGroup){const rule=selectedGroup.rules.find((item)=>item.id===id);if(rule){rule[key]=value;this.changed();}}},validate(){const groups=this.data.get("groups");const errors=[];groups.forEach((group)=>{if(!group.name.trim())errors.push("条件组名称不能为空");group.rules.forEach((rule)=>{if(!String(rule.value).trim())errors.push(`${group.name} 存在空比较值`);});});this.data.set("errors",errors);return!errors.length;},changed(){this.validate();this.scheduleAutosave();},scheduleAutosave(){clearTimeout(this.data.get("autosaveTimer"));if(!this.data.get("readonly")){this.data.set("autosaveTimer",setTimeout(()=>{this.data.set("savedAt","自动保存完成");},400));}},save(){if(!this.validate())return;this.data.set("savedAt",new Date().toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit"}));this.fire("save",{groups:JSON.parse(JSON.stringify(this.data.get("groups"))),expression:this.data.get("expression")});},togglePreview(){this.data.set("previewOpen",!this.data.get("previewOpen"));},computed:{selectedGroup(){const groups=this.data.get("groups");const selectedGroupId=this.data.get("selectedGroupId");return groups.find((group)=>group.id===selectedGroupId);},ruleCount(){const groups=this.data.get("groups");return groups.reduce((sum,group)=>sum+group.rules.length,0);},invalidRuleCount(){const groups=this.data.get("groups");return groups.reduce((sum,group)=>sum+group.rules.filter((rule)=>!String(rule.value).trim()).length,0);},expression(){const groups=this.data.get("groups");return groups.map((group)=>{const joiner=group.mode==="all"?" AND ":" OR ";return `(${group.rules.map((rule)=>`${rule.field} ${rule.operator} "${rule.value}"`).join(joiner)})`;}).join(" AND ");}}});</script><style>.rule-builder { width: 820px; padding: 24px; border: 1px solid #cbd5e1; border-radius: 7px; background: #f8fafc; color: #172026; font-family: Arial, sans-serif; }
.builder-header { display: flex; justify-content: space-between; gap: 24px; }
.builder-header h1 { margin: 3px 0; font-size: 24px; }
.builder-header p, .eyebrow { color: #64748b; font-size: 12px; }
.header-actions { display: flex; gap: 8px; }
.rule-builder button { padding: 8px 11px; border: 1px solid #334155; border-radius: 4px; background: #334155; color: #ffffff; cursor: pointer; }
.rule-builder button.secondary, .group-toolbar button, .rule-row button { background: #ffffff; color: #334155; border-color: #94a3b8; }
.builder-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 20px 0; }
.builder-stats article { padding: 12px; border-left: 3px solid #0f766e; background: #ffffff; }
.builder-stats article.warning { border-left-color: #dc2626; }
.builder-stats span { display: block; color: #64748b; font-size: 12px; }
.builder-stats strong { font-size: 22px; }
.builder-workspace { display: grid; grid-template-columns: 180px 1fr; min-height: 310px; border: 1px solid #d1d5db; background: #ffffff; }
.group-sidebar { padding: 12px; border-right: 1px solid #e2e8f0; background: #f1f5f9; }
.sidebar-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.group-tab { width: 100%; display: flex; justify-content: space-between; margin-bottom: 6px; background: #ffffff !important; color: #334155 !important; border-color: #cbd5e1 !important; text-align: left; }
.group-tab.active { border-color: #0f766e !important; background: #ccfbf1 !important; }
.group-editor { padding: 16px; }
.group-toolbar { display: grid; grid-template-columns: 1fr auto auto; gap: 8px; }
.group-toolbar input, .group-toolbar select, .rule-row input, .rule-row select { padding: 8px; border: 1px solid #94a3b8; }
.rule-list { display: grid; gap: 8px; margin: 16px 0; }
.rule-row { display: grid; grid-template-columns: 28px 1fr 1fr 1fr auto; gap: 7px; padding: 9px; border: 1px solid #e2e8f0; }
.rule-row.invalid { border-color: #fca5a5; background: #fff1f2; }
.rule-index { display: grid; place-items: center; color: #64748b; }
.add-rule { background: #0f766e !important; border-color: #0f766e !important; }
.empty-editor { display: grid; place-items: center; color: #94a3b8; }
.expression-preview { margin-top: 16px; padding: 14px; border: 1px solid #a7f3d0; background: #ecfdf5; }
.expression-preview > div { display: flex; justify-content: space-between; }
.expression-preview code { display: block; margin: 12px 0; white-space: normal; color: #065f46; }
.expression-preview ul { color: #b91c1c; }
.builder-footer { display: flex; justify-content: space-between; margin-top: 14px; color: #64748b; font-size: 12px; }
</style>
